package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="student_achievements") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class StudentAchievement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) Student student; @Column(nullable=false,length=40) String achievementType; @Column(nullable=false,length=200) String title; @Column(columnDefinition="TEXT") String description; @Column(nullable=false) LocalDate achievementDate; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by_teacher_id") Teacher createdByTeacher; @Column(name="created_at",updatable=false) LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();if(achievementDate==null)achievementDate=LocalDate.now();} }
